def embodied_carbon(bom, intensity):
    """bom: list of (part, material, finished_kg, buy_to_finished) tuples, where buy_to_finished >= 1
    is the kg of material bought per kg in the finished part (offcuts and scrap included).
    intensity: dict material -> kg CO2e per kg.
    Return (total, by_material): the total kg CO2e and a dict material -> kg CO2e."""
    return 0.0, {}

