def embodied_carbon(bom, intensity):
    by_material = {}
    for part, material, kg, buy in bom:
        if buy < 1:
            raise ValueError(f"{part}: cannot buy less material than ends up in the part")
        by_material[material] = by_material.get(material, 0.0) + intensity[material] * kg * buy
    return sum(by_material.values()), by_material

