def carbon_ranking(materials, mode):
    """materials: dict name -> (E in GPa, strength in MPa, density in kg/m^3, carbon intensity kg CO2e/kg).
    mode: "strength" (rank by c*rho/sigma), "beam" (c*rho/E**0.5) or "panel" (c*rho/E**(1/3)).
    Return the list of names from lowest to highest carbon for the job.
    Raise ValueError for any other mode."""
    return list(materials)

