def carbon_ranking(materials, mode):
    if mode == "strength":
        key = lambda v: v[3] * v[2] / v[1]
    elif mode == "beam":
        key = lambda v: v[3] * v[2] / v[0] ** 0.5
    elif mode == "panel":
        key = lambda v: v[3] * v[2] / v[0] ** (1 / 3)
    else:
        raise ValueError(f"unknown mode {mode!r}")
    return sorted(materials, key=lambda name: key(materials[name]))

